// harness.js against the Python harness: tests/fixtures/harness.json holds
// scenarios and what lab/harness.py logged and sent for each (generated by
// fixtures/make_harness_fixtures.py). Here the same scenarios run through the
// JavaScript harness and must give the same log and the same bytes to the model.
//
// One difference is known and accepted: JSON.parse loses whether a number in a
// tool input was written 1 or 1.0, so `args` and echoed `tool_use.input` are
// compared by value; every other line is compared character for character.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";

import { Config } from "../lab/config.js";
import { Harness } from "../lab/harness.js";
import { ModelError } from "../lab/model.js";
import { FakeModel, FakeWorld } from "./harness_fakes.js";

const scenarios = JSON.parse(readFileSync(new URL("./fixtures/harness.json", import.meta.url), "utf8"));

const answer = (item) => {
  if (item.r) {
    const stop = item.stop ?? (item.r.some((b) => b.type === "tool_use") ? "tool_use" : "end_turn");
    return { content: item.r, stop_reason: stop, model: "fake", input_tokens: 10, output_tokens: 5 };
  }
  return item.err !== undefined ? new ModelError(item.err, item.retry) : new TypeError(item.exc);
};

async function run(scenario) {
  const world = new FakeWorld();
  world.callS = scenario.callS ?? 0;
  const onCall = () => { world.t = Math.round((world.t + scenario.dtPerCall) * 100) / 100; };
  const model = new FakeModel(scenario.script.map(answer), { onCall, validate: false });
  const waits = [];
  const h = new Harness(world, model, new Config(scenario.config), { sleep: async (s) => { waits.push(s); } });
  h.start({ runLoop: false });
  for (const [op, arg, ...rest] of scenario.ops) {
    if (op === "enter") world.enter();
    else if (op === "leave") world.leave();
    else if (op === "say") world.say(arg);
    else if (op === "t") world.t = arg;
    else if (op === "step") await h.step();
    else if (op === "stop") await h.stop(arg, ...rest);
  }
  return { world, model, waits };
}

const strings = (value, out = []) => {
  if (typeof value === "string") out.push(value);
  else if (Array.isArray(value)) value.forEach((v) => strings(v, out));
  else if (value && typeof value === "object") Object.values(value).forEach((v) => strings(v, out));
  return out;
};

for (const scenario of scenarios) {
  test(`against Python: ${scenario.name}`, async () => {
    const { world, model, waits } = await run(scenario);
    const want = scenario.expected;

    // The log: same events, same order, same text.
    assert.equal(world.log.lines.length, want.lines.length);
    world.log.lines.forEach((line, i) => {
      const [mine, theirs] = [JSON.parse(line), JSON.parse(want.lines[i])];
      if (mine.type === "header") {
        delete mine.started_at;
        delete theirs.started_at;
      } else if (mine.type !== "call") {
        assert.equal(line, want.lines[i], `line ${i}`);
      }
      assert.deepEqual(mine, theirs, `line ${i}`);
    });

    // What the model was sent, request by request.
    assert.equal(model.sent.length, want.sent.length);
    model.sent.forEach((messages, i) => {
      const theirs = JSON.parse(want.sent[i]);
      assert.deepEqual(messages, theirs, `request ${i}`);
      assert.deepEqual(strings(messages), strings(theirs), `strings of request ${i}`);
    });
    assert.deepEqual(model.systems, want.systems);
    assert.deepEqual(waits, want.waits);
  });
}
